const HIGH = /grade|record|ledger|enroll|add\/drop|withdraw|transcript|conferral|graduat|hold|override|payment|refund|charge|credit|dispute|consent|revocation|legal hold|break glass|kill switch|cutover|rollback|standing|integrity|subject request|offboard|delet|invoice|dunning|approv/i;
const SENS = /grade|record|ledger|enroll|transcript|standing|advising notes|accommodation|integrity|disput|account|balance|charge|wellness|family|consent|aid|scholar/i;

function slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function archetype(n){
 n=n.toLowerCase();
 if(/ledger|audit|history|trail|events|log|version|entries|superseded/.test(n))return 'ledger';
 if(/overview|today|home|360|analytics|health|metrics|outcomes|slo|budget|dashboard|cash|forecast|aggregate|reports?$/.test(n))return 'dashboard';
 if(/queue|inbox|approvals|requests|reviews|errors|dead letter|incidents|cases|moderation|reconciliation|tickets|my work|appeals|regrades|referrals|disputes|alerts/.test(n))return 'queue';
 if(/studio|builder|editor|mapping|syllabus|assignments|assessments|rubric|question|resume|cover letter|writing|documents|deck|sheets|templates|course ai rules|workflow/.test(n))return 'builder';
 if(/policies|policy|settings|preferences|sso|scim|identity providers|roles|capabilit|flags|kill|modes|entitlements|plans$|classification|retention|keys|oauth|accessibility$|profile/.test(n))return 'settings';
 if(/calendar|schedule|time|window|office hours|appointments|events|session/.test(n))return 'calendar';
 if(/copilot|tutor|assistant|guide|planner|ask/.test(n))return 'assistant';
 return 'list';
}
function spec(d,mod){
 const [name,does]=mod.split('|');
 const key=d.id+':'+name;
 const high=HIGH.test(name);
 const sens=SENS.test(name)||/Education record/.test(d.cls);
 const arch=archetype(name);
 const root=(d.parent||d.id);
 const route='/'+slug(D.find(x=>x.id===root).short)+(d.parent?'/'+slug(d.short):'')+'/'+slug(name);
 const cap=slug(d.short).replace(/-/g,'_')+'.'+slug(name).replace(/-/g,'_');
 const status=OVERRIDE[key]||d.status;
 const primary={ledger:'Export',dashboard:'Open the top item',queue:'Take next',builder:'Publish',settings:'Save with preview',calendar:'Add',assistant:'Ask',list:'New'}[arch];
 return { key,name,does,domain:d.id,route,arch,cap:{read:cap+'.read',write:cap+(high?'.command':'.write')},high,sens,status,
  primary,
  flow: high?(d.flow==='register'?'register':(d.flow==='ai'?'ai':(['O','P','L','N'].includes(root)?'highrisk':'command'))):d.flow,
  states:['Default','Loading','Empty','Error','No permission','Offline'+(arch==='builder'?' (drafts saved locally)':'')],
  audit:[cap+'.viewed'].concat(arch==='list'||arch==='dashboard'?[]:[cap+(high?'.command_executed':'.changed')]).concat(high?[cap+'.approved',cap+'.rejected']:[]),
  ai: root==='F'?'This is an AI surface; follows the AI decision flow.':(high?'AI may explain or draft only. A person executes.':'AI may suggest and draft with approved sources.'),
  source: sens?'◆ Official (SIS/LMS/ERP until cutover) with freshness':(/student-owned|User/.test(d.authority+d.cls)?'○ Yours':'Semester native'),
  support: d.owner,
  slo: high?'Tier 0/1 — command path':d.slo,
  bridge: d.bridge,
  next: status==='Planned'||status==='Not started'?'Write spec + migration + RLS test on '+d.branch:(status==='Designed/documented only'?'Build screen against read model on '+d.branch:(status==='Static prototype only'?'Port prototype into app/ with real data on '+d.branch:(status==='Integrated only'||status==='Transitional'?'Plan dual run; define authority gate':'Add tests + release evidence')))
 };
}
const all=[];D.forEach(d=>d.modules.forEach(m=>all.push(spec(d,m))));

